const DOCTORS = {
  'dr-masoud': { name: 'Dr. Masoud', specialty: 'General Dentistry', calendarId: '<GOOGLE_CALENDAR_ID>' },
  'dr-paria':  { name: 'Dr. Paria',  specialty: 'Orthodontics',      calendarId: '<GOOGLE_CALENDAR_ID>' },
  'dr-parvin': { name: 'Dr. Parvin', specialty: 'Endodontics',        calendarId: '<GOOGLE_CALENDAR_ID>' },
  'dr-ali':    { name: 'Dr. Ali',    specialty: 'Implants',           calendarId: '<GOOGLE_CALENDAR_ID>' }
};

const SPECIALTY_MAP = {
  'general dentistry': 'dr-masoud',
  'general': 'dr-masoud',
  'orthodontics': 'dr-paria',
  'ortodoncia': 'dr-paria',
  'endodontics': 'dr-parvin',
  'endodoncia': 'dr-parvin',
  'implants': 'dr-ali',
  'implantes': 'dr-ali'
};

const body = $input.first().json.body;
const rawDoctorId = (body.doctor_id || '').toLowerCase().trim();
const rawSpecialty = (body.specialty || '').toLowerCase().trim();
let datePreference = body.date_preference || new Date().toISOString();

const doctorId = rawDoctorId ? rawDoctorId : SPECIALTY_MAP[rawSpecialty];
const doctor = doctorId ? DOCTORS[doctorId] : null;

if (!doctor) {
  return [{ json: { error: 'DOCTOR_NOT_FOUND', doctor_id: doctorId, specialty: rawSpecialty } }];
}

if (!datePreference.includes('+') && !datePreference.includes('Z')) {
  datePreference += '+02:00';
}

const targetDate = new Date(datePreference);
const searchStart = new Date(targetDate);
searchStart.setUTCHours(0, 0, 0, 0);
const searchEnd = new Date(searchStart.getTime() + 14 * 24 * 60 * 60 * 1000);

return [{ json: {
  doctor_id: doctorId,
  doctor_name: doctor.name,
  specialty: doctor.specialty,
  calendar_id: doctor.calendarId,
  date_preference: datePreference,
  search_start: searchStart.toISOString(),
  search_end: searchEnd.toISOString()
}}];

const resolveNode = $('Resolve Doctor').first().json;
const SLOT_MS = 45 * 60 * 1000;
const SLOTS_NEEDED = 3;
const WORK_START = 10;
const WORK_END_DEFAULT = 20;
const WORK_END_FRIDAY = 15;

function toMadridLocal(d) {
  return new Date(d.toLocaleString('en-US', { timeZone: 'Europe/Madrid' }));
}

const busyEvents = $input.all().map(item => ({
  start: new Date(item.json.start?.dateTime || item.json.start?.date),
  end: new Date(item.json.end?.dateTime || item.json.end?.date)
}));

let refDateStr = resolveNode.date_preference;
if (!refDateStr.includes('+') && !refDateStr.includes('Z')) refDateStr += '+02:00';
const refDate = new Date(refDateStr);
const nowMadrid = toMadridLocal(new Date());

let cursor = toMadridLocal(refDate);
cursor.setHours(WORK_START, 0, 0, 0);

const slots = [];
for (let day = 0; day < 14 && slots.length < SLOTS_NEEDED; day++) {
  const dow = cursor.getDay();
  if (dow !== 0 && dow !== 6) {
    const endHour = dow === 5 ? WORK_END_FRIDAY : WORK_END_DEFAULT;
    let slot = new Date(cursor);
    while (slot.getHours() < endHour) {
      const slotEnd = new Date(slot.getTime() + SLOT_MS);
      const isFuture = slot > nowMadrid;
      const isFree = !busyEvents.some(e => slot < e.end && slotEnd > e.start);
      if (isFuture && isFree) {
        const pad = n => String(n).padStart(2, '0');
        const offsetStr = slot.getMonth() >= 2 && slot.getMonth() <= 9 ? '+02:00' : '+01:00';
        slots.push({
          datetime: `${slot.getFullYear()}-${pad(slot.getMonth()+1)}-${pad(slot.getDate())}T${pad(slot.getHours())}:${pad(slot.getMinutes())}:00${offsetStr}`,
          date: `${slot.getDate()} ${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][slot.getMonth()]} ${slot.getFullYear()}`,
          time: `${pad(slot.getHours())}:${pad(slot.getMinutes())}`,
          doctor: resolveNode.doctor_name,
          doctor_id: resolveNode.doctor_id
        });
        if (slots.length >= SLOTS_NEEDED) break;
      }
      slot = new Date(slot.getTime() + SLOT_MS);
    }
  }
  cursor.setDate(cursor.getDate() + 1);
  cursor.setHours(WORK_START, 0, 0, 0);
}

return [{ json: {
  status: 'success',
  doctor: resolveNode.doctor_name,
  doctor_id: resolveNode.doctor_id,
  specialty: resolveNode.specialty,
  available_slots: slots,
  slots_found: slots.length
}}];
